#{code}
AND sku_id = #{skuId} GROUP BY virtual_warehouse_id

SELECT pa.approve_status AS status, pa.code AS sourceCode, pa.id AS sourceId, pad.dest_warehouse_id AS warehouseId, pad.apply_qty AS qty, pad.create_po_type AS createPoType, pa.approve_time AS estimatedPutAwayDate, pad.id AS detailId FROM ${tableName} AS pa INNER JOIN ${tableDetailName} AS pad ON pad.is_deleted = FALSE AND pad.purchase_application_id = pa."id" WHERE pad.sku_id = #{skuId}
AND ( (pa.status = 'approve' AND pa.createPoType IN (0, 1))
OR pa.status IN
#{code}
)
AND pa.status IN
#{code}

